protected void findPostingRebateDates(
    Set _rebateDates,
    Common _journalTransaction,
    InventDim _inventDimCriteria,
    InventDimParm _inventDimParm,
    TableGroupAll _accountCode,
    TAMRebateAccountRelation _accountRelation,
    TableGroupAll _itemCode,
    TAMRebateItemRelation _itemRelation)
{        
    next findPostingRebateDates(_rebateDates,
                                _journalTransaction,
                                _inventDimCriteria,
                                _inventDimParm,
                                _accountCode,
                                _accountRelation,
                                _itemCode,
                                _itemRelation);

    if (FeatureStateProvider::isFeatureEnabled(GUPGlobalEnableFeature::instance()) && rebateModule == ModuleInventCustVend::Cust)
    {            
        Set rebateToBeRemoved = new Set(Types::Int64);

        SetEnumerator rebateDatesEnumerator = _rebateDates.getEnumerator();
        while (rebateDatesEnumerator.moveNext())
        {          
            TAMRebateDate rebateDate = TAMRebateDate::find(rebateDatesEnumerator.current());
            TAMRebateTable rebateTable = TAMRebateTable::find(rebateDate.RebateId);

            boolean pricingAttributesAreMatched = GUPRebateMatchingHelper::checkIfPricingAttributesAreMatched(_journalTransaction, rebateQueryBuilder, rebateDate, rebateTable)
                && GUPRebateMatchingHelper::checkIfRecordLinkedWithPriceTree(_journalTransaction, rebateQueryBuilder, rebateTable);

            if (!pricingAttributesAreMatched)
            {                        
                rebateToBeRemoved.add(rebateDatesEnumerator.current());
            }
        }

        SetEnumerator filteredRebateDatesSetEnumerator = rebateToBeRemoved.getEnumerator();
        while (filteredRebateDatesSetEnumerator.moveNext())
        {
            _rebateDates.remove(filteredRebateDatesSetEnumerator.current());
        }
    }
}
